def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n < 5:
        if n == 4:
            if all(a == 'C' for a in opp):
                return 'D'
            else:
                if opp[-1] == 'D':
                    return 'D'
                return 'C'
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    if n == 5:
        if my[4] == 'D' and all(a == 'C' for a in opp[:4]):
            return 'C'
        else:
            if opp[-1] == 'D':
                return 'D'
            return 'C'

    mode = 'coop'
    if len(my) >= 6 and my[4] == 'D' and all(a == 'C' for a in opp[:4]):
        if opp[5] == 'C':
            mode = 'exploit'
        else:
            mode = 'coop'

    opp_d_count = sum(1 for a in opp if a == 'D')
    opp_d_rate = opp_d_count / n

    if opp_d_rate > 0.6:
        return 'D'

    if mode == 'exploit':
        recent_window = min(10, n)
        recent_opp = opp[-recent_window:]
        recent_d = sum(1 for a in recent_opp if a == 'D')
        if recent_d >= 3:
            mode = 'coop'
        else:
            if n >= 99:
                return 'D'
            last_opp = opp[-1]
            if last_opp == 'D':
                return 'C'
            window = min(25, n)
            my_recent = my[-window:]
            my_c_recent = sum(1 for a in my_recent if a == 'C')
            if n >= 25 and my_c_recent < 4:
                return 'C'
            return 'D'

    if n >= 99:
        return 'D'

    if n < 12 and opp_d_rate < 0.3:
        return 'C'

    last_opp = opp[-1]
    last_me = my[-1]

    if last_opp == 'D':
        if n >= 2 and opp[-2] == 'D' and last_me == 'D':
            if opp_d_rate < 0.5:
                return 'C'
        return 'D'
    else:
        return 'C'
